#ifndef ESCROW_POLICY_H
#define ESCROW_POLICY_H

#include <stddef.h>

// A role policy, generated by Nix (flake.nix: mkRole) and only read here:
//
//   env /nix/store/<hash>-escrow-role-<name>
//   store /nix/store/<hash>-<name>
//   ...
//
// env is the role's buildEnv: the agent's PATH is env/bin. The store lines
// are its full runtime closure (closureInfo), the only store paths the jail
// can see. env must be one of them.
struct policy {
  const char *env;
  char **store;
  size_t n;
};

// Host side, before the jail exists. Reads and validates path: every line
// is one of the two forms above, every store path is a well-formed
// /nix/store/<32 nix-base32 chars>-<name> that exists as a dir or regular
// file. Exits with status 1 on any malformed line or syscall failure.
void policy_load(struct policy *p, const char *path);

#endif
